const {test}=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs'),E=require('../engine.js');
function setup(){const dom={},events={},storage={};const el=s=>dom[s]??={innerHTML:'',textContent:'',style:{},showModal(){},close(){}};const context=vm.createContext({MNY:E,document:{querySelector:el,addEventListener:(type,fn)=>{const previous=events[type];events[type]=e=>{previous?.(e);fn(e)}}},localStorage:{getItem:k=>storage[k],setItem:(k,v)=>storage[k]=v},setInterval(){},setTimeout(){},clearTimeout(){},Date,console,crypto:require('node:crypto').webcrypto,confirm:()=>true});vm.runInContext(fs.readFileSync(require.resolve('../app.js'),'utf8'),context);const run=s=>vm.runInContext(s,context);const click=(a,i,r,extra={})=>events.click({target:{closest:()=>({dataset:{action:a,i:String(i),r,...extra}})}});const enter=nick=>{el("#nickname").value=nick;events.submit({target:{id:"seat-entry"},preventDefault(){}})};return {run,click,storage,enter};}
test('full party flow, tie, night, opener, automatic win and undo',()=>{const {run,click,storage}=setup();run(`db.players=Array.from({length:10},(_,i)=>({id:String(i),name:'Игрок '+(i+1)}))`);click('new');run(`g().seats.forEach((p,i)=>{p.id=String(i);p.role=['sheriff','mafia','mafia','don'][i]||'civil'})`);click('start');assert.equal(run('g().day'),0);click('foul',0);click('foul',0);click('foul',0);assert.equal(run('g().seats[0].muteDay'),0);click('next');assert.equal(run('g().speaker'),1);click('nominate',1);click('nominate',2);click('nominate',4);click('voting');run('g().ballot.votes={1:3,2:3,4:2}');click('count');assert.equal(run('g().ballot.stage'),'speech');assert.equal(run('g().ballot.candidates.join()'),'1,2');click('revote');run('g().ballot.votes={1:4,2:4}');click('count');assert.equal(run('g().ballot.stage'),'tie');click('lift');assert.equal(run('g().phase'),'night');run('g().nightDraft={kill:4,sheriff:3,don:0}');click('dawn');assert.equal(run('g().day'),1);assert.equal(run('g().opener'),3);assert.equal(run('g().nights[0].sheriff'),3);assert.equal(run('g().seats[4].alive'),false);click('remove',3);assert.equal(run('g().winner'),'red');assert.equal(run('db.games.length'),1);click('undo');assert.equal(run('g().phase'),'day');assert.equal(run('db.games.length'),0);assert.ok(storage['mny.v1']);});
test('timer pause and restart; setup rejects wrong composition',()=>{const {run,click}=setup();click('new');click('start');assert.equal(run('g().phase'),'setup');click('timer');assert.equal(run('typeof g().timer.started'),'number');click('timer');assert.equal(run('g().timer.started'),null);click('reset');assert.equal(run('g().timer.elapsed'),0);assert.ok(run('g().timer.started')>0)});

test('club nickname entry, duplicate protection, shuffle and separate roles',()=>{const {run,click,enter}=setup();run(`db.players=Array.from({length:10},(_,i)=>({id:String(i),name:i===0?'Alice':'Игрок '+(i+1)}))`);click('new');enter(' Alice ');assert.equal(run('name(g().seats[0].id)'),'Alice');enter('alice');assert.equal(run('g().seats.filter(p=>p.id).length'),1);click('roles');assert.notEqual(run('g().setupStep'),'roles');for(let i=2;i<=10;i++)enter('Игрок '+i);const before=run('g().seats.map(p=>p.id).join(",")');click('shuffle');const after=run('g().seats.map(p=>p.id).join(",")');assert.equal(new Set(after.split(',')).size,10);before.split(',').forEach((id,i)=>assert.notEqual(id,after.split(',')[i]));click('undo');assert.equal(run('g().seats.map(p=>p.id).join(",")'),before);click('roles');assert.equal(run('g().setupStep'),'roles');click('seating');click('unseat',3);enter('Игрок 4');assert.equal(run('db.players.length'),10);});
test('unknown nickname requires explicit guest choice and never enters club database',()=>{const {run,click,enter,storage}=setup();click('new');enter('Визитёр');assert.equal(run('g().seats.filter(p=>p.id).length'),0);click('guest');assert.equal(run('db.players.length'),0);assert.equal(run('name(g().seats[0].id)'),'Визитёр');const id=run('g().seats[0].id');enter('визитёр');click('guest');assert.equal(run('g().seats.filter(p=>p.id).length'),1);run(`end(null);db.active=null`);assert.equal(run(`name(${JSON.stringify(id)})`),'Визитёр');assert.equal(JSON.parse(storage['mny.v1']).players.length,0);});
test('player profiles store nickname and real name, reject duplicates and preserve identity on edit',()=>{const {run,click}=setup();click('add');run(`$('#playername').value='Феникс';$('#playerfullname').value='Анна';$('#playerform').onsubmit({preventDefault(){}})`);assert.equal(run('db.players[0].name'),'Феникс');assert.equal(run('db.players[0].fullName'),'Анна');const id=run('db.players[0].id');click('add');run(`$('#playername').value='феникс';$('#playerfullname').value='Другое имя';$('#playerform').onsubmit({preventDefault(){}})`);assert.equal(run('db.players.length'),1);run(`add(${JSON.stringify(id)});$('#playername').value='Phoenix';$('#playerfullname').value='Анна';$('#playerform').onsubmit({preventDefault(){}})`);assert.equal(run('db.players[0].id'),id);assert.equal(run('name(db.players[0].id)'),'Phoenix');});

test('role quotas hide filled roles, reject extra assignments and release changed roles',()=>{const {run,click}=setup();click('new');click('assign-role',0,'don');assert.equal(run("roleAvailable('don',1)"),false);assert.equal(run("roleAvailable('don',0)"),true);click('assign-role',1,'don');assert.equal(run('g().seats[1].roleAssigned'),undefined);click('assign-role',1,'sheriff');assert.equal(run("roleAvailable('sheriff',2)"),false);click('assign-role',2,'mafia');click('assign-role',3,'mafia');assert.equal(run("roleAvailable('mafia',4)"),false);assert.equal(run("compactRolePicker(g().seats[4],4).includes('data-r=\"mafia\"')"),false);click('clear-role',2);assert.equal(run("roleAvailable('mafia',4)"),true);click('undo');assert.equal(run("roleAvailable('mafia',4)"),false);});

test('clearing a role frees its quota and supports undo',()=>{const {run,click}=setup();click('new');click('assign-role',0,'don');click('clear-role',0);assert.equal(run('hasAssignedRole(g().seats[0])'),false);assert.equal(run("roleAvailable('don',1)"),true);click('undo');assert.equal(run('g().seats[0].role'),'don');assert.equal(run('hasAssignedRole(g().seats[0])'),true);});

test('last remaining role fills all unassigned seats in the same undoable action',()=>{const {run,click}=setup();click('new');click('assign-role',0,'mafia');click('assign-role',1,'mafia');click('assign-role',2,'don');assert.equal(run('g().seats.filter(hasAssignedRole).length'),3);click('assign-role',3,'sheriff');assert.equal(run('g().seats.every(hasAssignedRole)'),true);assert.equal(run("g().seats.filter(p=>p.role==='civil').length"),6);click('undo');assert.equal(run('g().seats.filter(hasAssignedRole).length'),3);});
test('autofill also handles a remaining special role',()=>{const {run,click}=setup();click('new');for(let i=0;i<6;i++)click('assign-role',i,'civil');click('assign-role',6,'mafia');click('assign-role',7,'mafia');assert.equal(run('g().seats.filter(hasAssignedRole).length'),8);click('assign-role',8,'don');assert.equal(run('g().seats[9].role'),'sheriff');assert.equal(run('g().seats[9].roleAssigned'),true);});

test('phase switch begins with day zero and advances the opener after a night',()=>{const {run,click}=setup();click('new');run(`g().seats.forEach((p,i)=>{p.id=String(i);p.role=['sheriff','mafia','mafia','don'][i]||'civil';p.roleAssigned=true})`);click('switch-day');assert.equal(run('g().day'),0);assert.equal(run('g().phase'),'day');click('switch-night');assert.equal(run('g().phase'),'night');click('switch-day');assert.equal(run('g().day'),1);assert.equal(run('g().opener'),1);});

test('day hides roles and night actions record shot, miss and separate checks',()=>{const {run,click}=setup();click('new');run(`g().phase='night';g().nightDraft={}`);assert.ok(run('initialNight().includes("night-board")'));click('night-mark',null,null,{key:'kill',number:'2'});assert.equal(run('g().nightDraft.kill'),2);click('night-miss');assert.equal(run('g().nightDraft.kill'),undefined);assert.equal(run('g().nightDraft.missed'),true);click('night-mark',null,null,{key:'kill',number:'4'});assert.equal(run('g().nightDraft.kill'),4);assert.equal(run('g().nightDraft.missed'),undefined);click('night-mark',null,null,{key:'sheriff',number:'1'});click('night-mark',null,null,{key:'don',number:'3'});assert.equal(run('g().nightDraft.sheriff'),1);assert.equal(run('g().nightDraft.don'),3);run("g().phase='day'");assert.equal(run('initialNight().includes("night-board")'),false);assert.equal(run('initialNight().includes("role-trigger")'),false);});

test('timer visual cue repeats at second fifty and stops on pause',()=>{const {run}=setup();for(const second of [50,51,54,110,170])assert.equal(run(`timerWarning(${second},true)`),true);for(const second of [0,49,55,60,109,115])assert.equal(run(`timerWarning(${second},true)`),false);assert.equal(run('timerWarning(50,false)'),false);});

test('day-night transitions preserve running and paused timer state',()=>{const {run,click}=setup();click('new');run(`g().seats.forEach((p,i)=>{p.id=String(i);p.role=['sheriff','mafia','mafia','don'][i]||'civil';p.roleAssigned=true});g().timer={elapsed:42000,started:12345}`);click('switch-day');click('switch-night');assert.equal(run('g().timer.elapsed'),42000);assert.equal(run('g().timer.started'),12345);run('g().timer.started=null');click('switch-day');click('switch-night');assert.equal(run('g().timer.elapsed'),42000);assert.equal(run('g().timer.started'),null);});
function readyParty(app){app.click('new');app.run(`g().seats.forEach((p,i)=>{p.id=String(i);p.role=['sheriff','mafia','mafia','don'][i]||'civil';p.roleAssigned=true})`)}
test('back to a night and forward reopens the same day without moving microphone or duplicating nights',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');assert.equal(run('g().opener'),0);click('phase-forward');click('night-mark',null,null,{key:'kill',number:'4'});click('night-mark',null,null,{key:'sheriff',number:'2'});click('phase-forward');assert.equal(run('g().opener'),1);assert.equal(run('g().day'),1);run('g().timer={elapsed:45000,started:1234}');for(let i=0;i<3;i++){click('phase-back');assert.equal(run('g().phase'),'night');assert.equal(run('g().seats[4].alive'),true);click('night-mark',null,null,{key:'sheriff',number:String(i+5)});click('phase-forward');assert.equal(run('g().opener'),1);assert.equal(run('g().day'),1);assert.equal(run('g().nights.length'),1);assert.equal(run('g().nights[0].sheriff'),i+5);assert.equal(run('g().seats[4].alive'),false);assert.equal(run('g().timer.started'),1234);assert.equal(run('g().timer.elapsed'),45000)}click('phase-forward');click('phase-forward');assert.equal(run('g().opener'),2);assert.equal(run('g().day'),2);});
test('correcting an old shot replaces the eliminated player and preserves the recorded opener',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('night-mark',null,null,{key:'kill',number:'4'});click('phase-forward');click('phase-back');click('night-mark',null,null,{key:'kill',number:'5'});click('phase-forward');assert.equal(run('g().seats[4].alive'),true);assert.equal(run('g().seats[5].alive'),false);assert.equal(run('g().nights[0].kill'),5);assert.equal(run('g().opener'),1);click('phase-back');click('night-miss');click('phase-forward');assert.equal(run('g().seats[5].alive'),true);assert.equal(run('g().nights[0].missed'),true);assert.equal(run('g().opener'),1);});
test('phase history survives saving and reloading',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('phase-forward');run('db=JSON.parse(JSON.stringify(db))');click('phase-back');click('phase-forward');assert.equal(run('g().day'),1);assert.equal(run('g().opener'),1);assert.equal(run('g().phaseHistory.length'),4);});
test('nomination order is preserved, can be corrected and single nominee gets all votes after first day',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run('g().day=1');click('nominate',7);click('nominate',4);click('nominate',6);assert.equal(run('g().nominated.join()'),'7,4,6');click('nominate',4);assert.equal(run('g().nominated.join()'),'7,6');click('nominate',7);run('g().timer={elapsed:53000,started:1234}');click('voting');assert.equal(run('g().ballot.votes[6]'),10);assert.equal(run('g().seats[6].alive'),false);assert.equal(run('g().phase'),'day');click('phase-forward');assert.equal(run('g().ballot.stage'),'result');assert.equal(run('g().timer.started'),1234);click('phase-back');click('phase-forward');assert.equal(run('g().phase'),'night');assert.equal(run('g().seats[6].alive'),false);click('phase-forward');assert.equal(run('g().opener'),1);});
test('three tied leaders alone proceed to revote and can all be eliminated after first day',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run('g().day=1');for(const i of [4,5,6,7])click('nominate',i);click('voting');run('g().ballot.votes={4:3,5:3,6:3,7:1}');click('count');assert.equal(run('g().ballot.stage'),'speech');assert.equal(run('g().ballot.candidates.join()'),'4,5,6');click('revote');run('g().ballot.votes={4:3,5:3,6:3}');click('count');assert.equal(run('g().ballot.stage'),'tie');click('lift');assert.equal(run('g().phase'),'night');for(const i of [4,5,6])assert.equal(run(`g().seats[${i}].alive`),false);assert.equal(run('g().seats[7].alive'),true);});
test('voting rejects excess votes and forward does not silently skip an unfinished ballot',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('nominate',4);click('nominate',5);click('phase-forward');assert.equal(run('g().phase'),'vote');run('g().ballot.votes={4:8,5:7}');click('count');assert.equal(run('g().phase'),'vote');click('phase-forward');assert.equal(run('g().phase'),'vote');click('cancel-vote');assert.equal(run('g().phase'),'day');assert.equal(run('g().nominated.join()'),'4,5');});
test('candidate reorder persists without duplicates and the cross removes only the selected nominee',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [7,3,5])click('nominate',i);run('reorderNominees(7,5,true)');assert.equal(run('g().nominated.join()'),'3,5,7');run('reorderNominees(7,3,false)');assert.equal(run('g().nominated.join()'),'7,3,5');click('remove-nominee',3);assert.equal(run('g().nominated.join()'),'7,5');click('undo');assert.equal(run('g().nominated.join()'),'7,3,5');click('voting');run('g().ballot.votes={7:2,3:3,5:5};reorderNominees(7,5,true)');assert.equal(run('g().nominated.join()'),'3,5,7');assert.equal(run('g().ballot.candidates.join()'),'3,5,7');assert.equal(run('g().ballot.votes[7]'),2);});

test('revote keeps the original order while nominee removal preserves player votes',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [4,5,6])click('nominate',i);click('voting');run('g().ballot.votes={4:4,5:4,6:2}');click('count');click('revote');run('g().ballot.votes={4:3,5:7};reorderNominees(5,4,false)');assert.equal(run('g().ballot.candidates.join()'),'4,5');assert.equal(run('g().ballot.votes[5]'),7);click('remove-nominee',4);assert.equal(run('g().ballot.candidates.join()'),'5');assert.equal(run('g().ballot.votes[5]'),10);click('remove-nominee',5);assert.equal(run('g().phase'),'day');});

test('sequential votes reduce remaining choices, correct previous count and finish inline',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [4,5,6])click('nominate',i);click('voting');assert.equal(run('votingCurrent()'),4);click('cast-vote',null,null,{count:'3'});assert.equal(run('votingRemaining()'),7);assert.equal(run('votingCurrent()'),5);click('vote-back');assert.equal(run('votingCurrent()'),4);assert.equal(run('votingRemaining()'),10);click('cast-vote',null,null,{count:'2'});click('cast-vote',null,null,{count:'3'});assert.equal(run('votingRemaining()'),5);click('cast-vote',null,null,{count:'6'});assert.equal(run('votingCurrent()'),6);click('cast-vote',null,null,{count:'5'});assert.equal(run('g().ballot.stage'),'result');assert.equal(run('g().phase'),'day');assert.equal(run('g().seats[6].alive'),false);assert.ok(run('votingInline().includes("№7 — 5 голосов")'));assert.equal(run('initialNight().includes("ballot-panel")'),false)});
test('all votes on an early candidate finish without visiting remaining candidates',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [4,5,6])click('nominate',i);click('voting');click('cast-vote',null,null,{count:'10'});assert.equal(run('g().ballot.stage'),'result');assert.equal(run('g().seats[4].alive'),false);assert.equal(run('votingInline().includes("vote-counts")'),false)});
test('sequential tie keeps only tied leaders for a fresh revote',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [4,5,6])click('nominate',i);click('voting');for(const count of [4,4,2])click('cast-vote',null,null,{count:String(count)});assert.equal(run('g().ballot.stage'),'speech');assert.equal(run('g().ballot.candidates.join()'),'4,5');click('revote');assert.equal(run('votingRemaining()'),10);click('cast-vote',null,null,{count:'5'});click('cast-vote',null,null,{count:'5'});assert.equal(run('g().ballot.stage'),'tie')});

test('night checks include eliminated players while shots only target living players',()=>{const app=setup(),{run,click}=app;readyParty(app);run("g().phase='night';g().nightDraft={};E.remove(g(),4,'Заголосован')");click('night-mark',null,null,{key:'sheriff',number:'4'});click('night-mark',null,null,{key:'don',number:'4'});assert.equal(run('g().nightDraft.sheriff'),4);assert.equal(run('g().nightDraft.don'),4);click('night-mark',null,null,{key:'kill',number:'4'});assert.equal(run('g().nightDraft.kill'),undefined);assert.ok(run('removalBar().includes(\'removal-number eliminated\')'));run("g().seats[4].reason='Удалён ночью'");assert.ok(run('removalBar().includes(\'removal-number removed\')'))});

test('restart voting restores its elimination and original candidate order without changing timer or fouls',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [6,4,5])click('nominate',i);run('g().seats[4].fouls=2;g().timer={elapsed:12345,started:6789}');click('voting');click('cast-vote',null,null,{count:'6'});click('cast-vote',null,null,{count:'2'});click('cast-vote',null,null,{count:'2'});assert.equal(run('g().seats[6].alive'),false);click('restart-voting');assert.equal(run('g().phase'),'vote');assert.equal(run('g().seats[6].alive'),true);assert.equal(run('g().ballot.candidates.join()'),'6,4,5');assert.equal(run('Object.keys(g().ballot.votes).length'),0);assert.equal(run('votingRemaining()'),10);assert.equal(run('g().seats[4].fouls'),2);assert.equal(run('g().timer.started'),6789);click('cast-vote',null,null,{count:'10'});assert.equal(run('g().seats[6].alive'),false)});
test('restart after a deciding vote removes the mistaken saved result from evening statistics',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run("[1,2].forEach(i=>E.remove(g(),i,'Убит ночью'))");for(const i of [3,4])click('nominate',i);click('voting');click('cast-vote',null,null,{count:'8'});assert.equal(run('g().phase'),'finished');assert.equal(run('db.games.length'),1);click('restart-voting');assert.equal(run('g().phase'),'vote');assert.equal(run('db.games.length'),0);assert.equal(run('g().winner'),null);assert.equal(run('g().seats[3].alive'),true);assert.equal(run('g().seats[1].alive'),false)});

test('confirmed game restart preserves seating, roles and guests but resets the entire party',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run("g().guests={'0':'Гость'};g().seats[4].fouls=3;g().seats[4].muteDay=1;E.remove(g(),5,'Убит ночью');g().timer={elapsed:12345,started:678};g().nightDraft={sheriff:4};g().nights=[{kill:5}];g().nominated=[4];g().spoken=[0,1];g().winner='red';g().ended='yesterday';db.games.push(JSON.parse(JSON.stringify(g())));var priorSeats=g().seats.map(p=>[p.id,p.role]);var priorId=g().id");click('restart-game');assert.equal(run('g().id===priorId'),true);assert.equal(run('JSON.stringify(g().seats.map(p=>[p.id,p.role]))===JSON.stringify(priorSeats)'),true);assert.equal(run('g().seats.every(p=>p.alive&&p.fouls===0&&p.muteDay===null&&p.roleAssigned)'),true);assert.equal(run('g().phase'),'setup');assert.equal(run('g().day'),-1);assert.equal(run('g().timer.elapsed'),0);assert.equal(run('g().timer.started'),null);assert.equal(run('g().nights.length+g().nominated.length+g().spoken.length'),0);assert.equal(run('g().phaseHistory'),undefined);assert.equal(run('g().ballot'),null);assert.equal(run('g().guests[0]'),'Гость');assert.equal(run('db.games.length'),0);click('phase-forward');assert.equal(run('g().opener'),0);assert.equal(run('g().day'),0)});
test('cancelled restart leaves the party untouched',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run('confirm=()=>false;var beforeRestart=JSON.stringify(db)');click('restart-game');assert.equal(run('JSON.stringify(db)===beforeRestart'),true)});

test('best move belongs to first-night victim and accepts at most three distinct seats',()=>{const app=setup(),{run,click}=app;readyParty(app);assert.equal(run('bestMoveBoard()'),'');run("g().nights=[{day:0,kill:4},{day:1,kill:5,nonNightDepartures:0}]");assert.equal(run('firstKilled()'),4);click('best-move',4);assert.equal(run('g().bestMoves[4].join()'),'4');click('best-move',4);for(const i of [1,2,3,6])click('best-move',i);assert.equal(run('g().bestMoves[4].join()'),'1,2,3');click('best-move',2);click('best-move',6);assert.equal(run('g().bestMoves[4].join()'),'1,3,6');run('db=JSON.parse(JSON.stringify(db))');assert.equal(run('g().bestMoves[4].join()'),'1,3,6');run('g().nights[0].kill=7');assert.equal(run('firstKilled()'),7);assert.equal(run('bestMoveBoard().includes("best-move-picked")'),false);run('g().nights[0].kill=4');assert.ok(run('bestMoveBoard().includes("best-move-picked")'));click('restart-game');assert.equal(run('g().bestMoves'),undefined);assert.equal(run('firstKilled()'),null)});

test('cyclic fouls require a mute circle choice, defer next-day mute and reset on fourth click',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(let n=0;n<3;n++)click('cycle-foul',4);assert.equal(run('g().seats[4].fouls'),3);assert.equal(run('g().seats[4].muteDay'),null);assert.equal(run('g().seats[4].mutePending'),true);click('choose-mute',4,null,{next:'1'});assert.equal(run('g().seats[4].muteDay'),1);assert.equal(run('muteBadge(g().seats[4]).includes("mute-indicator")'),false);click('phase-forward');click('phase-forward');assert.equal(run('muteBadge(g().seats[4]).includes("mute-indicator")'),true);click('cycle-foul',4);assert.equal(run('g().seats[4].fouls'),0);assert.equal(run('g().seats[4].muteDay'),null);for(let n=0;n<3;n++)click('cycle-foul',4);click('choose-mute',4,null,{next:'0'});assert.equal(run('g().seats[4].muteDay'),1);assert.equal(run('g().seats[4].alive'),true)});

test('victory keeps roster and night context and replaces only the timer with a cherry result card',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run("g().phase='night';end('red')");assert.equal(run('g().finishedPhase'),'night');assert.ok(run('game().includes("host-roster")'));assert.ok(run('game().includes("victory-card")'));assert.ok(run('game().includes("night-board")'));assert.equal(run(`game().includes('id="clock"')`),false);assert.equal(run(`game().includes('data-action="restart-voting"')`),false);assert.equal(run('game().match(/host-player-row/g).length'),10);run("g().phase='night';g().ballot={stage:'result',candidates:[4],votes:{4:10},eliminated:[4]}");assert.equal(run(`game().includes('data-action="restart-voting"')`),false)});

test('technical foul is a separate persistent toggle, supports correction, undo and game reset',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run('g().seats[4].fouls=2');click('technical-foul',4);assert.equal(run('g().seats[4].technicalFoul'),true);assert.equal(run('g().seats[4].fouls'),2);assert.equal(run('g().seats[4].alive'),true);click('phase-forward');click('phase-forward');assert.equal(run('g().seats[4].technicalFoul'),true);run('db=JSON.parse(JSON.stringify(db))');assert.equal(run('g().seats[4].technicalFoul'),true);click('technical-foul',4);assert.equal(run('g().seats[4].technicalFoul'),false);click('undo');assert.equal(run('g().seats[4].technicalFoul'),true);click('restart-game');assert.equal(run('g().seats[4].technicalFoul'),false)});

test('game fitting preserves natural size when it fits and scales proportionally when taller',()=>{const {run}=setup();assert.equal(run('gameViewportScale(900,720)'),.8);assert.equal(run('gameViewportScale(600,900)'),1);assert.equal(run('gameViewportScale(0,700)'),1);assert.equal(run('gameViewportScale(900,-10)'),0)});

test('correcting third foul updates already recorded nights and days and clears the future mute',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(let k=0;k<3;k++)click('cycle-foul',4);click('choose-mute',4,null,{next:'1'});click('phase-forward');click('phase-forward');assert.equal(run('g().seats[4].muteDay'),1);click('phase-back');click('phase-back');click('cycle-foul',4);assert.equal(run('g().seats[4].fouls'),0);assert.equal(run('g().seats[4].muteDay'),null);run('db=JSON.parse(JSON.stringify(db))');click('phase-forward');assert.equal(run('g().seats[4].fouls'),0);assert.equal(run('g().seats[4].muteDay'),null);click('phase-forward');assert.equal(run('g().seats[4].fouls'),0);assert.equal(run('muteBadge(g().seats[4]).includes("mute-indicator")'),false);for(let k=0;k<2;k++){click('phase-back');click('phase-forward');assert.equal(run('g().seats[4].fouls'),0);assert.equal(run('g().seats[4].muteDay'),null)}});
test('foul correction propagates from the actual previous value when phase baseline had no fouls',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(let k=0;k<3;k++)click('cycle-foul',4);click('choose-mute',4,null,{next:'1'});click('phase-forward');click('phase-back');assert.equal(run('g().phaseHistory[g().phaseCursor].baseline.seats[4].fouls'),0);click('cycle-foul',4);click('phase-forward');assert.equal(run('g().seats[4].fouls'),0);assert.equal(run('g().seats[4].muteDay'),null)});

test('mute indicator is beside player nickname and outside foul controls',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');run('g().seats[4].fouls=3;g().seats[4].muteDay=g().day');assert.equal(run('foulControl(g().seats[4],4).includes("mute-indicator")'),false);assert.ok(run(`initialNight().includes('</strong><span class="mute-indicator"')`))});

test('a miss on first game night prevents best move on all later kills',()=>{const app=setup(),{run}=app;readyParty(app);run('g().nights=[{day:0,missed:true},{day:1,kill:4},{day:2,kill:5}]');assert.equal(run('firstKilled()'),null);assert.equal(run('bestMoveInline(4)'), '')});
test('two voting or disciplinary departures before second night ends cancel best move',()=>{const app=setup(),{run,click}=app;readyParty(app);run("g().phase='day';g().day=1;g().nights=[{day:0,kill:4}];E.remove(g(),4,'Убит ночью');E.remove(g(),5,'Заголосован');g().bestMoves={4:[1,2,3]}");assert.equal(run('firstKilled()'),4);run("E.remove(g(),6,'Удалён днём')");assert.equal(run('firstKilled()'),null);click('best-move',7);assert.equal(run('g().bestMoves[4].join()'),'1,2,3');run("g().phase='night';g().nightDraft={missed:true};finishNight()");assert.equal(run('g().nights[1].nonNightDepartures'),2);assert.equal(run('firstKilled()'),null)});
test('night kills are excluded and departures after second night do not cancel best move',()=>{const app=setup(),{run}=app;readyParty(app);run("g().phase='night';g().day=1;g().nights=[{day:0,kill:4}];E.remove(g(),4,'Убит ночью');g().nightDraft={kill:5};finishNight()");assert.equal(run('g().nights[1].nonNightDepartures'),0);assert.equal(run('firstKilled()'),4);run("E.remove(g(),6,'Заголосован');E.remove(g(),7,'Удалён днём')");assert.equal(run('firstKilled()'),4);run('db=JSON.parse(JSON.stringify(db))');assert.equal(run('firstKilled()'),4)});

test('correcting an earlier removal updates best move eligibility at the recorded second-night cutoff',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('night-mark',null,null,{key:'kill',number:'4'});click('phase-forward');click('remove',5);click('remove',6);click('phase-forward');click('phase-forward');assert.equal(run('firstKilled()'),null);click('phase-back');click('phase-back');click('restore',6);click('phase-forward');click('phase-forward');assert.equal(run('g().nights[1].nonNightDepartures'),1);assert.equal(run('firstKilled()'),4)});

test('past checks persist as history marks and the same seat may be checked on multiple nights',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('night-mark',null,null,{key:'sheriff',number:'4'});click('night-mark',null,null,{key:'don',number:'5'});click('phase-forward');click('phase-forward');assert.equal(run('checkedPreviously("sheriff",4)'),true);assert.equal(run('checkedPreviously("don",5)'),true);assert.equal(run('checkedPreviously("kill",4)'),false);assert.equal(run('g().nightDraft.sheriff'),undefined);assert.ok(run('nightBoard().includes("checked-before")'));click('night-mark',null,null,{key:'sheriff',number:'4'});click('night-mark',null,null,{key:'don',number:'5'});assert.equal(run('g().nightDraft.sheriff'),4);assert.equal(run('g().nightDraft.don'),5);click('night-mark',null,null,{key:'sheriff',number:'4'});assert.equal(run('g().nightDraft.sheriff'),undefined);assert.equal(run('checkedPreviously("sheriff",4)'),true);click('night-mark',null,null,{key:'sheriff',number:'4'});click('phase-forward');assert.equal(run('g().nights.filter(n=>n.sheriff===4).length'),2);click('phase-back');click('phase-back');click('phase-back');assert.equal(run('checkedPreviously("sheriff",4)'),false)});

test('repeat check badges count past and current checks separately by role and support corrections',()=>{const app=setup(),{run,click}=app;readyParty(app);run("g().phase='night';g().day=2;g().nights=[{day:0,sheriff:4,don:5},{day:1,sheriff:4,don:4}];g().nightDraft={}");assert.equal(run('checkCount("sheriff",4)'),2);assert.equal(run('checkCount("don",4)'),1);assert.ok(run('checkNumber("sheriff",4).includes("×2")'));click('night-mark',null,null,{key:'sheriff',number:'4'});assert.ok(run('checkNumber("sheriff",4).includes("×3")'));click('night-mark',null,null,{key:'sheriff',number:'6'});assert.ok(run('checkNumber("sheriff",4).includes("×2")'));assert.equal(run('checkCount("sheriff",6)'),1);run('g().day=1;g().nightDraft={}');assert.equal(run('checkCount("sheriff",4)'),1);assert.equal(run('checkNumber("sheriff",4).includes("check-repeat")'),false);assert.equal(run('checkCount("kill",4)'),0)});

test('nine players after first game night may split three ways but cannot lift three on repeated tie',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('night-mark',null,null,{key:'kill',number:'7'});click('phase-forward');for(const i of [4,5,6])click('nominate',i);click('voting');for(let k=0;k<3;k++)click('cast-vote',null,null,{count:'3'});assert.equal(run('g().ballot.stage'),'speech');click('revote');for(let k=0;k<3;k++)click('cast-vote',null,null,{count:'3'});assert.equal(run('g().ballot.stage'),'tie');assert.equal(run('canLiftTiedCandidates()'),false);assert.equal(run(`votingInline().includes('data-action="lift"')`),false);click('lift');assert.equal(run('alive().length'),9);assert.equal(run('g().ballot.stage'),'tie');click('peace');assert.equal(run('g().phase'),'night');click('night-miss');click('phase-forward');assert.equal(run('g().nights.length'),2);assert.equal(run('alive().length'),9);for(const i of [4,5,6])click('nominate',i);click('voting');for(let k=0;k<3;k++)click('cast-vote',null,null,{count:'3'});click('revote');for(let k=0;k<3;k++)click('cast-vote',null,null,{count:'3'});assert.equal(run('canLiftTiedCandidates()'),true);click('lift');assert.equal(run('alive().length'),6)});

test('single nominee skips voting on first day but receives all votes on a later day',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('nominate',4);click('voting');assert.equal(run('g().phase'),'day');assert.equal(run('g().seats[4].alive'),true);click('phase-forward');assert.equal(run('g().phase'),'night');click('phase-forward');click('nominate',4);click('voting');assert.equal(run('g().ballot.stage'),'result');assert.equal(run('g().seats[4].alive'),false)});
test('guaranteed leader ends voting early for 6 of 10 and 1-2-1-3 of 9',()=>{const first=setup();readyParty(first);first.click('phase-forward');for(const i of [4,5,6])first.click('nominate',i);first.click('voting');first.click('cast-vote',null,null,{count:'6'});assert.equal(first.run('g().ballot.stage'),'result');assert.equal(first.run('Object.keys(g().ballot.votes).length'),1);const second=setup();readyParty(second);second.click('phase-forward');second.run("g().day=1;E.remove(g(),8,'Убит ночью')");for(const i of [4,5,6,7,0])second.click('nominate',i);second.click('voting');for(const count of [1,2,1,3])second.click('cast-vote',null,null,{count:String(count)});assert.equal(second.run('g().ballot.stage'),'result');assert.equal(second.run('g().ballot.eliminated.join()'),'7');assert.equal(second.run('Object.keys(g().ballot.votes).length'),4)});
test('voting continues when remaining votes could tie the current leader',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [4,5,6])click('nominate',i);click('voting');click('cast-vote',null,null,{count:'5'});assert.equal(run('g().ballot.stage'),'votes');assert.equal(run('votingRemaining()'),5)});
test('extra speeches and revote keep initial nomination order',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [7,4,6,5])click('nominate',i);click('voting');for(const count of [3,3,3])click('cast-vote',null,null,{count:String(count)});assert.equal(run('g().ballot.stage'),'speech');assert.equal(run('g().ballot.candidates.join()'),'7,4,6');run('reorderNominees(6,7,false)');assert.equal(run('g().ballot.candidates.join()'),'7,4,6');click('revote');assert.equal(run('votingCurrent()'),7);click('cast-vote',null,null,{count:'3'});assert.equal(run('votingCurrent()'),4)});
test('lifting obeys first-day two-player cap, night thresholds and half-table limit',()=>{const app=setup(),{run}=app;readyParty(app);run("g().phase='vote';g().day=0;g().ballot={stage:'tie',candidates:[4,5,6]}");assert.equal(run('canLiftTiedCandidates()'),false);run('g().ballot.candidates=[4,5]');assert.equal(run('canLiftTiedCandidates()'),true);run('g().day=1;g().ballot.candidates=[4,5,6,7,8];g().nights=[{day:0,missed:true}]');assert.equal(run('canLiftTiedCandidates()'),false);run('g().nights.push({day:1,missed:true})');assert.equal(run('canLiftTiedCandidates()'),true);run("E.remove(g(),9,'Убит ночью')");assert.equal(run('canLiftTiedCandidates()'),false);run('g().ballot.candidates=[4,5,6]');assert.equal(run('canLiftTiedCandidates()'),true);run('g().nights.pop()');assert.equal(run('canLiftTiedCandidates()'),false)});
test('a pre-result disqualification cancels current voting; further same-round removals skip only next day',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [0,1])click('nominate',i);click('voting');click('cast-vote',null,null,{count:'2'});click('remove',4);assert.equal(run('g().phase'),'day');assert.equal(run('g().ballot'),null);assert.ok(run('votingBlockReason()'));assert.equal(run('g().seats[0].alive'),true);click('remove',5);click('remove',6);assert.equal(run('g().voteDisqualifications.map(e=>e.targets[0]).join()'),'0,1,1');click('voting');assert.equal(run('g().phase'),'day');click('phase-forward');assert.equal(run('g().phase'),'night');click('phase-forward');assert.equal(run('g().day'),1);assert.ok(run('votingBlockReason()'));click('phase-forward');click('phase-forward');assert.equal(run('g().day'),2);assert.equal(run('votingBlockReason()'),'');click('restart-game');assert.equal(run('g().voteDisqualifications.length'),0)});
test('disqualifications after a guaranteed result skip the two following ballots',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(const i of [4,5,6])click('nominate',i);click('voting');click('cast-vote',null,null,{count:'6'});assert.equal(run('g().ballot.stage'),'result');click('remove',7);click('remove',8);assert.equal(run('g().voteDisqualifications.map(e=>e.targets[0]).join()'),'1,2');run('db=JSON.parse(JSON.stringify(db))');click('phase-forward');click('night-mark',null,null,{key:'kill',number:'1'});click('phase-forward');assert.ok(run('votingBlockReason()'));click('nominate',5);click('voting');assert.equal(run('g().phase'),'day');click('phase-forward');click('phase-forward');assert.ok(run('votingBlockReason()'));click('phase-forward');click('phase-forward');assert.equal(run('g().day'),3);assert.equal(run('votingBlockReason()'),'')});
test('restoring an erroneously disqualified player removes the voting penalty from future phases',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('remove',4);click('phase-forward');click('phase-forward');click('phase-back');click('phase-back');click('restore',4);assert.equal(run('g().voteDisqualifications.length'),0);assert.equal(run('votingBlockReason()'),'');click('phase-forward');assert.equal(run('g().voteDisqualifications.length'),0);click('phase-forward');assert.equal(run('g().voteDisqualifications.length'),0)});

test('correcting the first disqualification reallocates the remaining penalty to current ballot',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('remove',4);click('remove',5);assert.equal(run('g().voteDisqualifications.map(e=>e.targets[0]).join()'),'0,1');click('phase-forward');click('phase-forward');click('phase-back');click('phase-back');click('restore',4);assert.equal(run('g().voteDisqualifications.map(e=>e.targets[0]).join()'),'0');click('phase-forward');click('phase-forward');assert.equal(run('votingBlockReason()'),'')});
test('protocol opens separately and saves extra points in active game and evening statistics',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('red')");assert.ok(run('finished().includes("Протокол игры")'));click('protocol');assert.equal(run('view'),'protocol');assert.ok(run('protocol().includes("Победа города")'));assert.equal(run('protocol().match(/protocol-player/g).length'),10);click('score-up',4);assert.equal(run('g().seats[4].extraScoreTenths'),2);assert.equal(run('db.games[0].seats[4].extraScoreTenths'),2);assert.equal(run('E.score(g(),g().seats[4]).total'),2.2);run('db=JSON.parse(JSON.stringify(db))');assert.equal(run('E.score(protocolGame(),protocolGame().seats[4]).total'),2.2);assert.ok(run('history().includes("2,2")'));click('score-down',4);click('score-down',4);assert.equal(run('g().seats[4].extraScoreTenths'),-1);click('undo');assert.equal(run('g().seats[4].extraScoreTenths'),0)});
test('protocol validates manual scores, caps bounds, and is unavailable for unfinished games',()=>{const app=setup(),{run,click}=app;readyParty(app);click('score-up',4);assert.equal(run('g().seats[4].extraScoreTenths'),0);run("end('black')");click('protocol');for(const raw of [0.1,0.3,2.2,-4.1,-0.15,''])run(`updateProtocolScore(4,${JSON.stringify(raw)})`);assert.equal(run('g().seats[4].extraScoreTenths'),0);run('updateProtocolScore(4,2)');click('score-up',4);assert.equal(run('g().seats[4].extraScoreTenths'),20);run('updateProtocolScore(4,-4)');click('score-down',4);assert.equal(run('g().seats[4].extraScoreTenths'),-40);run('updateProtocolScore(4,-0.1)');assert.equal(run('g().seats[4].extraScoreTenths'),-1);click('restart-game');assert.equal(run('g().seats[4].extraScoreTenths'),0)});
test('archived protocols stay editable without reopening or changing another active party',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('red');var scoredId=g().id");click('closegame');click('protocol',null,null,{id:run('scoredId')});assert.equal(run('view'),'protocol');click('score-up',0);assert.equal(run('db.games[0].seats[0].extraScoreTenths'),2);assert.equal(run('g()'),null);run("db.active=E.create(Array.from({length:10},(_,i)=>'new'+i));db.active.id='other-game'");click('score-down',0);assert.equal(run('db.games[0].seats[0].extraScoreTenths'),0);assert.equal(run('db.active.id'),'other-game');assert.equal(run('db.active.seats[0].extraScoreTenths'),0);assert.equal(run('db.active.log.length'),0)});
test('protocol uses a single icon role column and stores editable comments with scores',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('red')");click('protocol');assert.equal(run('protocol().match(/role-trigger assigned protocol-role/g).length'),10);assert.ok(run('protocol().includes("protocol-role-heading")'));assert.equal(run('protocol().match(/data-score-comment=/g).length'),10);run("updateProtocolComment(4,'Сильная аргументация и точное голосование');flushProtocolComment()");assert.equal(run('g().seats[4].extraScoreComment'),'Сильная аргументация и точное голосование');assert.equal(run('db.games[0].seats[4].extraScoreComment'),'Сильная аргументация и точное голосование');click('score-up',4);assert.equal(run('g().seats[4].extraScoreTenths'),2);assert.equal(run('g().seats[4].extraScoreComment'),'Сильная аргументация и точное голосование');run('db=JSON.parse(JSON.stringify(db))');assert.ok(run('protocol().includes("Сильная аргументация")'));run("updateProtocolComment(4,'');flushProtocolComment()");assert.equal(run('g().seats[4].extraScoreComment'),'');click('restart-game');assert.equal(run('g().seats[4].extraScoreComment'),'')});
test('protocol comments escape markup and group one editing session into one undo action',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('black')");click('protocol');run("var beforeCommentUndo=undo.length;updateProtocolComment(4,'a');updateProtocolComment(4,'ab');updateProtocolComment(4,'</textarea><script>bad</script>');flushProtocolComment()");assert.equal(run('undo.length-beforeCommentUndo'),1);assert.equal(run('protocol().includes("<script>bad</script>")'),false);assert.ok(run('protocol().includes("&lt;/textarea&gt;")'));click('undo');assert.equal(run('g().seats[4].extraScoreComment'),'');run("updateProtocolComment(4,'x'.repeat(1500));flushProtocolComment()");assert.equal(run('g().seats[4].extraScoreComment.length'),1000)});
test('archived comments preserve an unrelated active party',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('red');var commentGameId=g().id");click('closegame');click('protocol',null,null,{id:run('commentGameId')});run("db.active=E.create(Array.from({length:10},(_,i)=>'new'+i));db.active.id='different';updateProtocolComment(0,'Точная игра');flushProtocolComment()");assert.equal(run('db.games[0].seats[0].extraScoreComment'),'Точная игра');assert.equal(run('db.active.seats[0].extraScoreComment'),'');assert.equal(run('db.active.log.length'),0)});
test('protocol shares table fitting while losses award one point before signed extras',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('black')");click('protocol');assert.equal(run('isTableView()'),true);assert.ok(run("$('#app').innerHTML.includes('game-canvas protocol-canvas')"));assert.equal(run('E.score(protocolGame(),protocolGame().seats[4]).base'),1);run('updateProtocolScore(4,0.4)');assert.equal(run('E.score(protocolGame(),protocolGame().seats[4]).total'),1.4);run('updateProtocolScore(4,-4)');assert.equal(run('E.score(protocolGame(),protocolGame().seats[4]).total'),-3);assert.ok(run('protocol().includes("Поражение — 1 балл")'));assert.ok(run('protocol().includes("Результат")'));click('history');assert.equal(run('isTableView()'),false)});

test('timer warning frame lives outside the fitted canvas and clears when navigating away or pausing',()=>{const app=setup(),{run,click}=app;readyParty(app);run("var frameOn=false,panelOn=false;$('.timer-peripheral').classList={toggle(name,on){if(name==='active')frameOn=on}};$('.timer').classList={toggle(name,on){if(name==='timer-alert')panelOn=on}};g().timer={elapsed:50000,started:Date.now()};tick()");assert.equal(run('frameOn&&panelOn'),true);run("view='home';tick()");assert.equal(run('frameOn||panelOn'),false);run("view='game';g().timer.started=null;tick()");assert.equal(run('frameOn||panelOn'),false);run('g().timer={elapsed:110000,started:Date.now()};tick()');assert.equal(run('frameOn&&panelOn'),true);assert.equal(run('timer().includes("timer-peripheral")'),false)});
test('window warning border is a body sibling of main rather than a transformed child',()=>{const html=fs.readFileSync(require.resolve('../index.html'),'utf8');assert.equal((html.match(/class="timer-peripheral"/g)||[]).length,1);assert.ok(html.indexOf('class="timer-peripheral"')>html.indexOf('</main>'));const css=fs.readFileSync(require.resolve('../style.css'),'utf8');assert.ok(css.includes('.timer-peripheral.active'));assert.equal(css.includes('.timer-alert .timer-peripheral'),false)});

test('expanded comment placement stays within viewport and can grow above bottom rows',()=>{const {run}=setup();assert.equal(run('protocolCommentBounds({right:1000,top:600},360,300,1280,720).top'),408);assert.equal(run('protocolCommentBounds({right:1000,top:200},360,300,1280,720).top'),200);assert.equal(run('protocolCommentBounds({right:300,top:200},360,1000,390,700).height'),676);assert.equal(run('protocolCommentBounds({right:300,top:200},360,1000,390,700).left'),12);assert.equal(run('protocolCommentBounds({right:1000,top:200},360,300,1280,720).width'),360)});
test('protocol keeps fixed-size comment slots when editors expand',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('red')");click('protocol');assert.equal(run('protocol().match(/protocol-comment-slot/g).length'),10);assert.equal(run('protocol().match(/data-score-comment=/g).length'),10)});
function seedRatingParty(app,id,created,winner='red'){app.run(`var ratingParty=E.create(Array.from({length:10},(_,i)=>String(i)));ratingParty.id=${JSON.stringify(id)};ratingParty.created=${JSON.stringify(created)};ratingParty.ended=${JSON.stringify(created)};ratingParty.phase='finished';ratingParty.winner=${JSON.stringify(winner)};ratingParty.seats.forEach((p,i)=>p.role=['sheriff','mafia','mafia','don'][i]||'civil');db.games.push(ratingParty)`)}
test('evening boundary is 06:00 Madrid including after-midnight games and summer time',()=>{const {run}=setup();for(const [date,key] of [['2026-11-12T00:30:00Z','2026-11-11'],['2026-11-12T04:59:59Z','2026-11-11'],['2026-11-12T05:00:00Z','2026-11-12'],['2026-07-01T03:59:59Z','2026-06-30'],['2026-07-01T04:00:00Z','2026-07-01']])assert.equal(run(`eveningKey(${JSON.stringify(date)})`),key);assert.equal(run('eveningKey("bad-date")'),null)});
test('rating includes only completed results from the selected evening and deduplicates active games',()=>{const app=setup(),{run}=app;seedRatingParty(app,'one','2026-11-11T19:00:00Z');seedRatingParty(app,'two','2026-11-12T01:00:00Z','black');seedRatingParty(app,'next','2026-11-12T05:00:00Z');seedRatingParty(app,'previous','2026-11-10T20:00:00Z');seedRatingParty(app,'cancelled','2026-11-11T20:00:00Z',null);run("db.active=JSON.parse(JSON.stringify(db.games[1]));db.active.seats[4].extraScoreTenths=4");assert.equal(run('eveningGames("2026-11-11").map(p=>p.id).join()'),'one,two');assert.equal(run('eveningRating("2026-11-11").rows.length'),10);assert.equal(run('eveningRating("2026-11-11").rows.find(p=>p.id==="4").totalTenths'),34);assert.equal(run('eveningRating("2026-11-11").redWins'),1);assert.equal(run('eveningRating("2026-11-11").blackWins'),1)});
test('rating sums win/loss points and signed extras exactly and gives equal totals equal places',()=>{const app=setup(),{run}=app;seedRatingParty(app,'one','2026-11-12T18:00:00Z');seedRatingParty(app,'two','2026-11-12T19:00:00Z','black');run("db.games[0].seats[4].extraScoreTenths=4;db.games[1].seats[4].extraScoreTenths=-1;db.games[0].seats[5].extraScoreTenths=4;db.games[1].seats[5].extraScoreTenths=-1");assert.equal(run('eveningRating("2026-11-12").rows[0].totalTenths'),33);assert.equal(run('eveningRating("2026-11-12").rows[0].place'),1);assert.equal(run('eveningRating("2026-11-12").rows[1].place'),1);assert.equal(run('eveningRating("2026-11-12").rows[2].place'),3);assert.equal(run('eveningRating("2026-11-12").rows[0].baseTenths'),30);assert.equal(run('eveningRating("2026-11-12").rows[0].extraTenths'),3);assert.equal(run('eveningRating("2026-11-12").rows[0].played'),2);assert.equal(run('eveningRating("2026-11-12").rows[0].wins'),1);assert.equal(run('eveningRating("2026-11-12").rows[0].losses'),1)});
test('rating is read-only, supports empty evenings and links protocols back to the selected date',()=>{const app=setup(),{run,click}=app;seedRatingParty(app,'one','2026-11-10T18:00:00Z');run("var beforeRating=JSON.stringify(db);ratingMode='evening';ratingDate='2026-11-10';view='rating'");assert.ok(run('rating().includes("Клубный рейтинг")'));assert.equal(run('JSON.stringify(db)===beforeRating'),true);click('protocol',null,null,{id:'one'});assert.equal(run('protocolReturnView'),'rating');assert.ok(run('protocol().includes("К рейтингу")'));click('score-up',4);click('rating-return');assert.equal(run('view'),'rating');assert.equal(run('ratingDate'),'2026-11-10');assert.equal(run('eveningRating(ratingDate).rows.find(p=>p.id==="4").totalTenths'),22);run("ratingDate='2026-10-01'");assert.ok(run('rating().includes("rating-empty")'));assert.equal(run('isTableView()'),false)});

test('finished party statistics and protocol return open its evening rating',()=>{const app=setup(),{run,click}=app;readyParty(app);run("end('red')");assert.ok(run('finished().includes(\'data-action="rating"\')'));click('protocol');assert.equal(run('protocolReturnView'),'rating');assert.equal(run('ratingDate===eveningKey(g().created)'),true);click('rating-return');assert.equal(run('view'),'rating');assert.equal(run('eveningRating(ratingDate).games.length'),1)});
test('three completed game nights with no exits end automatically in a draw, excluding role night',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(let night=0;night<3;night++){click('phase-forward');click('night-miss');click('phase-forward');if(night<2)assert.equal(run('g().phase'),'day')}assert.equal(run('g().phase'),'finished');assert.equal(run('g().winner'),'draw');assert.equal(run('g().nights.length'),3);assert.equal(run('g().drawAlive.length'),10);assert.ok(run('finished().includes("Ничья")'));click('protocol');assert.ok(run('protocol().includes("0,5 оставшимся")'));assert.equal(run('E.score(g(),g().seats[0]).base'),.5);run('updateProtocolScore(0,0.2)');assert.equal(run('g().seats[0].extraScoreTenths'),0);assert.equal(run('eveningRating(eveningKey(g().created)).draws'),1);assert.equal(run('eveningRating(eveningKey(g().created)).rows[0].draws'),1);assert.equal(run('eveningRating(eveningKey(g().created)).rows[0].losses'),0)});
test('a night kill resets the draw window; an earlier victim gets 1 plus allowed extras at draw',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('night-mark',null,null,{key:'kill',number:'4'});click('phase-forward');for(let n=0;n<2;n++){click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().phase'),'day')}click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().winner'),'draw');assert.equal(run('g().nights.length'),4);assert.equal(run('E.score(g(),g().seats[4]).base'),1);click('protocol');run('updateProtocolScore(4,0.4)');assert.equal(run('E.score(g(),g().seats[4]).total'),1.4);assert.equal(run('db.games[0].seats[4].extraScoreTenths'),4)});
test('daytime disqualification resets no-exit window instead of drawing after the prior first night',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('night-miss');click('phase-forward');click('remove',4);for(let n=0;n<2;n++){click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().phase'),'day')}click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().winner'),'draw');assert.equal(run('g().nights.length'),4)});
test('protocol validates PU cap, displays separate best move points and includes them in evening totals',()=>{const app=setup(),{run,click}=app;readyParty(app);run("g().nights=[{day:0,kill:4},{day:1,nonNightDepartures:0}];g().bestMoves={4:[1,2,3]};E.remove(g(),4,'Убит ночью');end('red')");click('protocol');run('updateProtocolScore(4,1)');assert.equal(run('g().seats[4].extraScoreTenths'),0);run('updateProtocolScore(4,0.8)');click('score-up',4);assert.equal(run('g().seats[4].extraScoreTenths'),8);assert.equal(run('E.score(g(),g().seats[4]).total'),3.6);assert.ok(run('protocol().includes("protocol-lh")'));assert.equal(run('eveningRating(eveningKey(g().created)).rows.find(p=>p.id==="4").bestMoveTenths'),8);assert.equal(run('eveningRating(eveningKey(g().created)).rows.find(p=>p.id==="4").totalTenths'),36);run('db=JSON.parse(JSON.stringify(db))');assert.equal(run('E.score(g(),g().seats[4]).total'),3.6)});
test('correcting an old shot to a miss reevaluates the draw at the recorded third-night ending',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(let n=0;n<3;n++){click('phase-forward');if(n===0)click('night-mark',null,null,{key:'kill',number:'4'});else click('night-miss');click('phase-forward')}assert.equal(run('g().phase'),'day');for(let n=0;n<5;n++)click('phase-back');click('night-miss');for(let n=0;n<5;n++)click('phase-forward');assert.equal(run('g().winner'),'draw');assert.equal(run('g().drawAlive.length'),10)});
test('night correction updates later survivor baselines and prevents a premature draw',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');for(let n=0;n<3;n++){click('phase-forward');if(n<2)click('night-mark',null,null,{key:'kill',number:String(4+n)});else click('night-miss');click('phase-forward')}for(let n=0;n<5;n++)click('phase-back');click('night-miss');for(let n=0;n<5;n++)click('phase-forward');assert.equal(run('g().winner'),null);assert.equal(run('g().nights[1].startedAlive.length'),10);click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().winner'),null);click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().winner'),'draw');assert.equal(run('g().nights.length'),5)});
test('a daytime vote elimination resets draw interval just like a shot or removal',()=>{const app=setup(),{run,click}=app;readyParty(app);click('phase-forward');click('phase-forward');click('night-miss');click('phase-forward');click('nominate',4);click('voting');assert.equal(run('g().seats[4].alive'),false);for(let n=0;n<2;n++){click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().winner'),null)}click('phase-forward');click('night-miss');click('phase-forward');assert.equal(run('g().winner'),'draw');assert.equal(run('g().nights.length'),4)});

test('seasons use calendar quarters with winter spanning years',()=>{const {run}=setup();for(const [key,start,end,title] of [['2027-01-15','2026-12-01','2027-02-28','Зима 2026–2027'],['2028-02-29','2027-12-01','2028-02-29','Зима 2027–2028'],['2026-03-01','2026-03-01','2026-05-31','Весна 2026'],['2026-08-31','2026-06-01','2026-08-31','Лето 2026'],['2026-11-30','2026-09-01','2026-11-30','Осень 2026']]){const p=run(`seasonPeriod(${JSON.stringify(key)})`);assert.equal(p.start,start);assert.equal(p.end,end);assert.equal(p.title,title)}});
test('season rating spans evenings and respects the six AM season boundary',()=>{const app=setup(),{run,click}=app;seedRatingParty(app,'autumn','2026-11-30T20:00:00Z');seedRatingParty(app,'late-autumn','2026-12-01T04:59:59Z');seedRatingParty(app,'winter','2026-12-01T05:00:00Z');seedRatingParty(app,'winter-end','2027-02-28T20:00:00Z');seedRatingParty(app,'spring','2027-03-01T05:00:00Z');assert.equal(run('eveningRating("2026-12-01","2027-02-28").games.map(p=>p.id).join()'),'winter,winter-end');run("ratingDate='2027-01-01'");assert.ok(run('rating().includes("Зима 2026–2027")'));assert.ok(run('rating().includes("rating-table")'));click('rating');assert.equal(run('ratingMode'),'season');assert.equal(run('ratingDate===eveningKey()'),true);click('rating-evening');assert.equal(run('ratingMode'),'evening')});
